import { readFile, writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'

const source = fileURLToPath(new URL('../public/passwords/frontend-blocklist.txt', import.meta.url))
const destination = fileURLToPath(new URL('../src/default-blocklist.ts', import.meta.url))
const text = await readFile(source, 'utf8')

await writeFile(
  destination,
  [
    '// Generated by scripts/embed-blocklist.mjs. Do not edit by hand.',
    `export const DEFAULT_FRONTEND_BLOCKLIST_TEXT: string = ${JSON.stringify(text)}`,
    '',
  ].join('\n'),
  'utf8',
)
